using Microsoft.Extensions.ML;
using ChurnPredictor.Models;
using ChurnPredictor.Services;

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddSingleton<ChurnModelService>();
builder.Services.AddPredictionEnginePool<ChurnInput, ChurnPrediction>()
    .FromFile(Path.Combine(AppContext.BaseDirectory, "Data", "churn_model.zip"));

var app = builder.Build();

var modelService = app.Services.GetRequiredService<ChurnModelService>();
modelService.TrainAndSaveModel();

app.MapGet("/", () => "Hello");

app.MapPost("/predict", (ChurnInput input, PredictionEnginePool<ChurnInput, ChurnPrediction> pool) =>
{
    var prediction = pool.Predict(input);
    return Results.Json(new { willChurn = prediction.PredictedLabel, probability = prediction.Probability });
});

app.Run();

