 using Microsoft.ML;
 using ChurnPredictor.Models;

 namespace ChurnPredictor.Services;

 public class ChurnModelService
 {
     private readonly ILogger<ChurnModelService> _logger;

     public ChurnModelService(ILogger<ChurnModelService> logger)
     {
         _logger = logger;
     }

     public ITransformer TrainAndSaveModel()
     {
         var mlContext = new MLContext(seed: 42);

         var dataPath = Path.Combine(AppContext.BaseDirectory, "Data", "customers.csv");
         var data = mlContext.Data.LoadFromTextFile<ChurnInput>(
             dataPath, hasHeader: true, separatorChar: ',');

         var split = mlContext.Data.TrainTestSplit(data, testFraction: 0.2, seed: 42);

         var pipeline = mlContext.Transforms.Conversion
                 .MapValue("Label",
                     new Dictionary<string, bool> { { "Yes", true }, { "No", false } },
                     inputColumnName: nameof(ChurnInput.Churned))
             .Append(mlContext.Transforms.Categorical
                 .OneHotEncoding("RegionEncoded", nameof(ChurnInput.Region)))
             .Append(mlContext.Transforms.Concatenate("Features",
                 nameof(ChurnInput.Age),
                 nameof(ChurnInput.Income),
                 "RegionEncoded",
                 nameof(ChurnInput.PurchaseHistory)))
             .Append(mlContext.Transforms.NormalizeMinMax("Features"))
             .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression(
                 labelColumnName: "Label", featureColumnName: "Features"));

         _logger.LogInformation("Training churn prediction model...");
         var model = pipeline.Fit(split.TrainSet);

         var predictions = model.Transform(split.TestSet);
         var metrics = mlContext.BinaryClassification.Evaluate(predictions, labelColumnName: "Label");

         _logger.LogInformation("Model evaluation — Accuracy: {Accuracy:F4}, AUC: {Auc:F4}, F1: {F1:F4}",
             metrics.Accuracy, metrics.AreaUnderRocCurve, metrics.F1Score);

         var modelPath = Path.Combine(AppContext.BaseDirectory, "Data", "churn_model.zip");
         mlContext.Model.Save(model, data.Schema, modelPath);
         _logger.LogInformation("Model saved to {Path}", modelPath);

         return model;
     }
 }

